package edu.nd.dronology.ui.vaadin.flightroutes;

import java.util.List;

import org.vaadin.addon.leaflet.LMarker;

import com.vaadin.data.Binder;
import com.vaadin.data.converter.StringToFloatConverter;
import com.vaadin.ui.Grid;
import com.vaadin.ui.Grid.Column;
import com.vaadin.ui.Grid.SelectionMode;
import com.vaadin.ui.TextField;
import com.vaadin.ui.renderers.ButtonRenderer;
import com.vaadin.ui.renderers.TextRenderer;

import edu.nd.dronology.ui.vaadin.utils.UIWayPoint;
import elemental.json.JsonValue;

/**
 * This is the class that contains all logic for displaying the latitude and
 * longitude locations of the pins on the map. There is code in its constructor
 * that ensures the values input into the table are usable. It contains
 * functions that cause the grid to enter and exit edit mode, functions to add
 * and delete a column of Delete buttons, and it contains a grid that displays
 * information about waypoints.
 * 
 * @author Michelle Galbavy
 */

public class FRTableDisplay { 
	private Grid<UIWayPoint> grid = new Grid<>(UIWayPoint.class);
	private FRMapComponent mapComponent;
	private boolean hasDeleteColumn;
	private TextField latitude = new TextField();
	private TextField longitude = new TextField();
	private TextField altitude = new TextField();
	private TextField transitSpeed = new TextField();
	private Binder<UIWayPoint> binder = new Binder<>();

	@SuppressWarnings("serial")
	public FRTableDisplay(FRMapComponent mapComponent) {
		this.mapComponent = mapComponent;
		binder = grid.getEditor().getBinder();

		binder.forField(latitude).withConverter(new StringToFloatConverter("Must enter a number."))
				.withValidator(latitude -> latitude >= -90 && latitude <= 90, "Must be between -90 and 90.")
				.bind(UIWayPoint::getLatitudeFloat, UIWayPoint::setLatitudeFloat);
		// Check that the input for latitude is a float between -90 and 90.

		binder.forField(longitude).withConverter(new StringToFloatConverter("Must enter a number."))
				.withValidator(longitude -> longitude >= -180 && longitude <= 180, "Must be between -180 and 180.")
				.bind(UIWayPoint::getLongitudeFloat, UIWayPoint::setLongitudeFloat);
		// Check that the input for longitude is a float between -180 and 180.

		binder.forField(altitude).withConverter(new StringToFloatConverter("Must enter a number."))
				.withValidator(altitude -> altitude > 0 && altitude <= 100, "Must be between 0 and 100.")
				.bind(UIWayPoint::getAltitudeFloat, UIWayPoint::setAltitudeFloat);
		// Check that the input for altitude is a float between 0 and 100.

		binder.forField(transitSpeed).withConverter(new StringToFloatConverter("Must be a number."))
				.withValidator(transitSpeed -> transitSpeed > 0, "Must be greater than zero.")
				.bind(UIWayPoint::getTransitSpeedFloat, UIWayPoint::setTransitSpeedFloat);
		// Check that the input for transit speed is a float greater than 0.

		grid.addStyleName("fr_table_component");
		grid.getColumns().stream().forEach(c -> c.setSortable(false));
		grid.getColumns().stream().forEach(c -> {
			if (c.getCaption().equals("Id") || c.getCaption().equals("Reached")) {
				grid.removeColumn(c);
			} else if (c.getCaption().equals("Order")) {
				c.setRenderer(new TextRenderer() {
					/**
					 * 
					 */
					private static final long serialVersionUID = -3894899353779064347L;

					@Override
					public JsonValue encode(Object value) {
						int order = (Integer) value + 1;
						return super.encode(order);
					}
				});
				c.setCaption("#");
			}
		});
		grid.setColumnOrder("order", "latitude", "longitude", "altitude", "transitSpeed");
		// Sets grid styling (doesn't show Id or Reached columns, and renames Order
		// column to #, and sets the order in which the columns appear).

		grid.setColumnResizeMode(null);
		grid.setSelectionMode(SelectionMode.NONE);

		grid.getColumn("latitudeFloat").setHidden(true);
		grid.getColumn("longitudeFloat").setHidden(true);
		grid.getColumn("altitudeFloat").setHidden(true);
		grid.getColumn("transitSpeedFloat").setHidden(true);
	}

	public void makeEditable() {
		grid.getColumn("latitude").setEditorComponent(latitude);
		grid.getColumn("longitude").setEditorComponent(longitude);
		grid.getColumn("altitude").setEditorComponent(altitude);
		grid.getColumn("transitSpeed").setEditorComponent(transitSpeed);
		// Makes all columns editable.

		grid.getEditor().setEnabled(true);
		grid.getEditor().addSaveListener(event -> {
			updatePinForWayPoint(event.getBean());
			grid.getEditor().cancel();
			mapComponent.updateLinesAndGrid();
		});
		addButtonColumn();
		// Adds a column of Delete buttons to the grid when in edit mode.
	}

	public void makeUneditable() {
		grid.getEditor().setEnabled(false);
		removeButtonColumn();
		// Removes the column of Delete buttons from the grid when in edit mode.
	}

	public void updatePinForWayPoint(UIWayPoint wayPoint) {
		LMarker pin = mapComponent.getMapUtilities().getPinById(wayPoint.getId());
		if (pin != null) {
			pin.getPoint().setLat(Double.valueOf(wayPoint.getLatitude()));
			pin.getPoint().setLon(Double.valueOf(wayPoint.getLongitude()));
			pin.setData(wayPoint);
		}
	}

	public void addButtonColumn() {
		if (!hasDeleteColumn) {
			// This check ensures that only one column of Delete buttons will be added to
			// the grid at a time.
			hasDeleteColumn = true;
			grid.addColumn(event -> "Delete", new ButtonRenderer<UIWayPoint>(clickEvent -> {
				if (mapComponent.getMapUtilities().isEditable()) {
					mapComponent.getDeleteWayPointConfirmation().showWindow(clickEvent);
					;
				}
			}));
		}
	}

	public void removeButtonColumn() {
		hasDeleteColumn = false;
		grid.getColumns().stream().forEach(c -> {
			if (!c.getCaption().equals("Id") && !c.getCaption().equals("Reached") && !c.getCaption().equals("Latitude")
					&& !c.getCaption().equals("Longitude") && !c.getCaption().equals("#")
					&& !c.getCaption().equals("Altitude") && !c.getCaption().equals("Transit Speed")) {
				// This round-about checking method is necessary because the column of Delete
				// buttons has an empty caption.
				grid.removeColumn(c);
			}
		});
	}

	public Grid<UIWayPoint> getGrid() {
		return grid;
	}

	public void setGrid(List<UIWayPoint> points) {
		// Takes in waypoints, sets their order, then adds them to the grid.
		grid.setItems(points);
	}
},The _RouteCreationUI_ shall support route creation and modification in tabular mode by displaying a editable table showing each waypoint and the velocity of the UAV approaching the waypoint.,"As a user engaged in managing flight routes for drones, you can utilize this system to effectively display and interact with your drone route data. The system is designed to showcase the latitude, longitude, altitude, and transit speed of various waypoints on a map, serving as a tool for planning and visualization.

package edu.nd.dronology.ui.vaadin.flightroutes;

import java.io.File;

import com.vaadin.event.LayoutEvents.LayoutClickEvent;
import com.vaadin.event.LayoutEvents.LayoutClickListener;
import com.vaadin.server.FileResource;
import com.vaadin.server.VaadinService;
import com.vaadin.ui.Button;
import com.vaadin.ui.CheckBox;
import com.vaadin.ui.CustomComponent;
import com.vaadin.ui.HorizontalLayout;
import com.vaadin.ui.Label;
import com.vaadin.ui.TextField;
import com.vaadin.ui.VerticalLayout;
import com.vaadin.ui.themes.ValoTheme;

import edu.nd.dronology.services.core.info.FlightRouteInfo;
import edu.nd.dronology.ui.vaadin.flightroutes.windows.FRUnsavedChangesConfirmation.ChangeType;

/**
 * 
 * This is the info bar above the map that gives route information and contains
 * the edit and delete buttons.
 * 
 * @author jhollan4
 *
 */

@SuppressWarnings("serial")
public class FRMetaInfo extends CustomComponent {
	/** 
	 * 
	 */
	private static final long serialVersionUID = -1187868736573439881L;
	private FRMapComponent map;
	private Label nameLabel;
	private Label waypointNumLabel;
	private Label descriptionLabel;

	private HorizontalLayout allContent;
	private VerticalLayout leftSide;
	private VerticalLayout rightSide;
	private CheckBox autoZoomingCheckBox;
	private CheckBox tableViewCheckBox;

	public FRMetaInfo(FRMapComponent map) {
		this.map = map;

		waypointNumLabel = new Label("");
		nameLabel = new Label("No Route Selected");

		// The two labels are initialized separately so that they can be changed
		// independently later.
		HorizontalLayout labels = new HorizontalLayout();
		labels.addComponents(nameLabel, waypointNumLabel);

		autoZoomingCheckBox = new CheckBox("Zoom to Route");
		autoZoomingCheckBox.setValue(true);
		tableViewCheckBox = new CheckBox("Table View");
		tableViewCheckBox.setValue(true);

		String basepath = VaadinService.getCurrent().getBaseDirectory().getAbsolutePath();

		FileResource editIcon = new FileResource(new File(basepath + "/VAADIN/img/editButtonFull.png"));
		Button editButton = new Button("Edit");
		editButton.setIcon(editIcon);
		editButton.addStyleName(ValoTheme.BUTTON_ICON_ONLY);

		FileResource deleteIcon = new FileResource(new File(basepath + "/VAADIN/img/deleteButtonFull.png"));
		Button deleteButton = new Button("Delete");
		deleteButton.setIcon(deleteIcon);
		deleteButton.addStyleName(ValoTheme.BUTTON_ICON_ONLY);

		// A layout is used to hold the description label so that a LayoutClickListener
		// can be added later.
		HorizontalLayout descriptionHolder = new HorizontalLayout();
		descriptionLabel = new Label("");
		descriptionHolder.addComponent(descriptionLabel);

		HorizontalLayout buttons = new HorizontalLayout();
		buttons.addComponents(editButton, deleteButton);

		HorizontalLayout checkboxes = new HorizontalLayout();
		checkboxes.addComponents(autoZoomingCheckBox, tableViewCheckBox);

		leftSide = new VerticalLayout();
		leftSide.addComponents(labels, descriptionHolder);

		rightSide = new VerticalLayout();
		rightSide.addComponents(buttons, checkboxes);

		// "leftSide" includes the labels and description, while "rightSide" includes
		// the buttons and checkboxes.
		allContent = new HorizontalLayout();
		allContent.setStyleName("fr_route_meta_info");
		allContent.addStyleName("has_route");
		// only add left side when initialized, right side is added when a route is
		// selected
		allContent.addComponent(leftSide);

		rightSide.addStyleName("route_meta_controls");
		leftSide.addStyleName("route_meta_label_description");

		TextField nameEditField = new TextField();
		TextField descriptionEditField = new TextField();

		nameEditField.setStyleName("name_edit_field");
		descriptionEditField.setStyleName("description_edit_field");
		nameLabel.setStyleName("name_lable");
		waypointNumLabel.setStyleName("waypoint_num_lable");
		descriptionLabel.setStyleName("description_lable");

		// Click listeners for the edit and delete buttons.
		editButton.addClickListener(e -> {
			map.getEditModeController().enterEditMode();
		});
		deleteButton.addClickListener(e -> {
			if (map.getMapUtilities().isEditable()) {
				map.getMainLayout().getUnsavedChangesConfirmation().showWindow(map.getMainLayout().getControls()
						.getInfoPanel().getHighlightedFRInfoBox().getFlightRouteInfo().getName(),
						ChangeType.DELETE_ROUTE, e);
			} else {
				map.getMainLayout().getDeleteRouteConfirmation().showWindow(
						map.getMainLayout().getControls().getInfoPanel().getHighlightedFRInfoBox().getFlightRouteInfo(),
						e);
			}
		});

		// Double click allows user to edit label by turning it into a textbox.
		labels.addLayoutClickListener(new LayoutClickListener() {
			private static final long serialVersionUID = 1L;

			@Override
			public void layoutClick(LayoutClickEvent event) {
				if (!map.getMapUtilities().isEditable())
					return;
				if (event.getClickedComponent() == nameLabel) {
					if (event.isDoubleClick()) {
						// Change layout to accommodate for the textfield.
						allContent.removeAllComponents();

						HorizontalLayout nameArea = new HorizontalLayout();
						nameEditField.setValue(nameLabel.getValue());
						nameArea.addComponents(nameEditField, waypointNumLabel);

						VerticalLayout textLayout = new VerticalLayout();
						textLayout.addComponents(nameArea, descriptionHolder);
						textLayout.addStyleName("route_meta_label_description");

						allContent.addComponents(textLayout, rightSide);
					}
				}
			}
		});
		// Double click allows user to edit description by turning it into a textbox.
		descriptionHolder.addLayoutClickListener(new LayoutClickListener() {
			private static final long serialVersionUID = 1L;

			@Override
			public void layoutClick(LayoutClickEvent event) {
				if (!map.getMapUtilities().isEditable())
					return;
				if (event.getClickedComponent() == descriptionLabel) {
					if (event.isDoubleClick()) {
						// Change layout to accommodate for the textfield.
						allContent.removeAllComponents();
						labels.removeAllComponents();

						VerticalLayout textLayout = new VerticalLayout();
						textLayout.addStyleName("route_meta_label_description");
						labels.addComponents(nameLabel, waypointNumLabel);

						descriptionEditField.setValue(descriptionLabel.getValue());
						textLayout.addComponents(labels, descriptionEditField);
						allContent.addComponents(textLayout, rightSide);
					}
				}
			}
		});
		// Textfield turns back into the correct label once the user clicks away.
		nameEditField.addBlurListener(e -> {
			nameLabel.setValue(nameEditField.getValue());

			labels.removeAllComponents();
			labels.addComponents(nameLabel, waypointNumLabel);

			leftSide.removeAllComponents();
			leftSide.addComponents(labels, descriptionHolder);

			allContent.removeAllComponents();
			allContent.addComponents(leftSide, rightSide);

			rightSide.addStyleName("route_meta_controls");
		});
		// Once the user clicks away from the description field, the correct label is
		// shown.
		descriptionEditField.addBlurListener(e -> {
			descriptionLabel.setValue(descriptionEditField.getValue());

			labels.removeAllComponents();
			labels.addComponents(nameLabel, waypointNumLabel);

			leftSide.removeAllComponents();
			leftSide.addComponents(labels, descriptionHolder);

			allContent.removeAllComponents();
			allContent.addComponents(leftSide, rightSide);

			rightSide.addStyleName("route_meta_controls");
		});
		// Hides the table.
		tableViewCheckBox.addValueChangeListener(event -> {
			if (tableViewCheckBox.getValue()) {
				map.displayTable();
			} else {
				map.displayNoTable();
			}
		});

		setCompositionRoot(allContent);
	}

	public String getRouteName() {
		return nameLabel.getValue();
	}

	public void setRouteName(String name) {
		nameLabel.setValue(name);
	}

	public String getRouteDescription() {
		return descriptionLabel.getValue();
	}

	public void setRouteDescription(String description) {
		descriptionLabel.setValue(description);
	}

	public void showInfoForSelectedRoute(FlightRouteInfo info) {
		nameLabel.setValue(info.getName());
		descriptionLabel.setValue(info.getDescription());
		setNumWaypoints(info.getWaypoints().size());

		allContent.addComponent(rightSide);
	}

	public void showInfoWhenNoRouteIsSelected() {
		nameLabel.setValue("No Route Selected");
		descriptionLabel.setValue("");
		waypointNumLabel.setValue("");
		allContent.removeComponent(rightSide);
	}

	// Ensures that the correct description of waypoints is shown.
	public void setNumWaypoints(int num) {
		if (num == 1) {
			waypointNumLabel.setValue("(" + num + " waypoint)");
		} else {
			waypointNumLabel.setValue("(" + num + " waypoints)");
		}
	}

	public boolean isAutoZoomingChecked() {
		return autoZoomingCheckBox.getValue() == true;
	}

	public boolean isTableViewChecked() {
		return tableViewCheckBox.getValue() == true;
	}
},The UI shall provide respective fields for displaying and modifying the ID  textual description  waypoints  and other route information.,"The interface serves as an interactive information bar above a map within a flight route management tool. Users can view the details of a selected route, such as its name, description, and the number of waypoints. If no route is selected, it displays a message indicating this status. Users have the option to edit these details, which transforms the display fields to editable text boxes upon double-clicking. There are also options to manage the view and interaction modes, such as toggling between table and graphical views and enabling automatic zoom to a route. Edit or delete actions are facilitated by dedicated buttons, which prompt confirmations when needed, especially for deletions. This interface assists users in managing and editing route information efficiently, emphasizing waypoint metrics and offering flexible interaction modalities for detailed control.","[-0.028244961, 0.011625608, -0.008479262, 0.01700182, -0.024564601, 0.038015958, -0.032358304, 0.03986335, -0.034956206, -0.056259, 0.023727499, 0.027754245, 0.012765799, 0.004614883, -0.024261512, 0.011272006, -0.034927342, -0.0006314344, -0.0219667, 0.022428548, 0.011084379, 0.0054303356, -0.049764242, 0.017492536, -0.017579133, -0.018661592, -0.002756662, 0.012888477, -0.0128740445, 0.020999704, -0.01710285, 0.027653217, 0.0316078, -0.0069169123, -0.0017346403, 0.04621378, 0.030395446, 0.017247178, 0.010615313, 0.027811978, 0.02802847, -0.017073985, -0.0041602505, 0.05311265, -0.010745209, -0.036284022, -0.009619451, 0.006227747, -0.017867789, -0.021995565, -0.031492338, -0.06373518, 0.009006058, -0.012174054, 0.044164322, 0.029486181, 0.029356286, 0.046386972, -0.024910988, -0.00800298, 0.009034923, -0.014367837, -0.010781291, 0.02010487, 0.01788222, -0.008969976, -0.027797544, 0.014136913, -0.030077925, -5.3615542e-05, -0.03622629, 0.038766462, 0.014981231, -0.0005